CREATE TABLE users(id INTEGER PRIMARY KEY, chat INTEGER NOT NULL, tz TEXT NOT NULL, reminders INTEGER NOT NULL DEFAULT 0, ai_consent INTEGER NOT NULL DEFAULT 0, water_hour1 INTEGER NOT NULL DEFAULT 13, water_hour2 INTEGER NOT NULL DEFAULT 17, water_pct1 REAL NOT NULL DEFAULT 30, water_pct2 REAL NOT NULL DEFAULT 60, kcal_pct REAL NOT NULL DEFAULT 80);
CREATE TABLE goals(user INTEGER NOT NULL REFERENCES users(id), day TEXT NOT NULL, kcal REAL NOT NULL, protein REAL NOT NULL, fat REAL NOT NULL, carbs REAL NOT NULL, water INTEGER NOT NULL, PRIMARY KEY(user,day));
CREATE TABLE entries(id INTEGER PRIMARY KEY, user INTEGER NOT NULL REFERENCES users(id), kind TEXT NOT NULL CHECK(kind IN ('water','weight','meal')), day TEXT NOT NULL, utc INTEGER NOT NULL, tz TEXT NOT NULL, amount INTEGER NOT NULL DEFAULT 0, kcal REAL NOT NULL DEFAULT 0, protein REAL NOT NULL DEFAULT 0, fat REAL NOT NULL DEFAULT 0, carbs REAL NOT NULL DEFAULT 0, description TEXT NOT NULL DEFAULT '', items TEXT NOT NULL DEFAULT '[]', draft INTEGER UNIQUE, deleted INTEGER NOT NULL DEFAULT 0);
CREATE UNIQUE INDEX one_weight ON entries(user,day) WHERE kind='weight' AND deleted=0;
CREATE INDEX entries_day ON entries(user,day);
CREATE TABLE sessions(user INTEGER PRIMARY KEY REFERENCES users(id), state TEXT NOT NULL, payload TEXT NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE drafts(id INTEGER PRIMARY KEY, user INTEGER NOT NULL REFERENCES users(id), kind TEXT NOT NULL, day TEXT NOT NULL, tz TEXT NOT NULL, description TEXT NOT NULL, estimate TEXT NOT NULL DEFAULT '{}', version INTEGER NOT NULL DEFAULT 1, status TEXT NOT NULL DEFAULT 'pending', expires INTEGER NOT NULL);
CREATE TABLE inbox(id INTEGER PRIMARY KEY, payload TEXT NOT NULL, done INTEGER NOT NULL DEFAULT 0);
CREATE TABLE state(key TEXT PRIMARY KEY, value INTEGER NOT NULL);
INSERT INTO state VALUES('offset',0);
CREATE TABLE jobs(id INTEGER PRIMARY KEY, draft INTEGER NOT NULL REFERENCES drafts(id), version INTEGER NOT NULL, user INTEGER NOT NULL REFERENCES users(id), day TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', attempts INTEGER NOT NULL DEFAULT 0, due INTEGER NOT NULL DEFAULT 0);
CREATE TABLE notices(user INTEGER NOT NULL REFERENCES users(id), day TEXT NOT NULL, rule TEXT NOT NULL, PRIMARY KEY(user,day,rule));
CREATE TABLE outbox(id INTEGER PRIMARY KEY, user INTEGER NOT NULL, method TEXT NOT NULL, payload TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, due INTEGER NOT NULL DEFAULT 0, done INTEGER NOT NULL DEFAULT 0, expires INTEGER NOT NULL DEFAULT 0);
CREATE INDEX outbox_due ON outbox(done,due);
CREATE TABLE schema_migrations(version INTEGER PRIMARY KEY, applied_at INTEGER NOT NULL);
INSERT INTO schema_migrations VALUES(1,unixepoch());
